import { Component, Element, Host, Listen, Prop, h } from "@stencil/core";
import Updater from "./Updater";

/**
 * Tracks an element's scrollposition and adds classes on change of scroll position
 * Tracks the first child element by default
 * Also adds classes to the closest container elements, drawer, modal and stepper.
 */
@Component({
	tag: "hbr-scroll-view",
	styleUrl: "scroll-view.scss",
	shadow: true,
})
export class HbrScrollView {
	@Element() el: HTMLElement;

	@Prop() anchor: string | null = null;
	private updater: Updater;

	@Listen("slotchange")
	slotChangeHandler() {
		this.initializeUpdater();
	}

	componentDidLoad() {
		this.initializeUpdater();
	}

	disconnectedCallback() {
		if (this.updater) {
			this.updater.off();
		}
	}

	private initializeUpdater() {
		const anchorEl =
			this.anchor && this.el.parentElement
				? this.el.parentElement.querySelector(this.anchor)
				: this.el?.children[0];

		if (!anchorEl) {
			console.warn("Scroll view cannot find an anchor to observe scroll.");
			return;
		}

		this.updater = new Updater();
		this.updater.on(anchorEl as HTMLElement);
	}

	render() {
		return (
			<Host>
				<div class="base" part="base">
					<slot />
				</div>
			</Host>
		);
	}
}
